package net.flashlight.battery;
import java.util.*;
/** Two held sources; bounded client-only collision budget, no world writes and no chunk loading. */
public final class Light6{
 public static final int SIZE=12,MAX=2,BUDGET=48;static Object world;static final LinkedHashMap<Object,Lamp>cache=new LinkedHashMap<>();static int turn;public static int lastRays;static int ticks;static final List<Object>blockEntities=new ArrayList<>();
 public static class Lamp{Object owner;double range,tan;double[]origin,forward,right,up,shadowOrigin,shadowForward,shadowRight,shadowUp,workingOrigin,workingForward,workingRight,workingUp;float[]distance=new float[SIZE*SIZE],working=new float[SIZE*SIZE];int cursor;Lamp(Object p){owner=p;}}
 static Object mc(){return R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");}static double num(Object v){return ((Number)v).doubleValue();}static double[]plus(double[]a,double[]b,double k){return new double[]{a[0]+b[0]*k,a[1]+b[1]*k,a[2]+b[2]*k};}static double dot(double[]a,double[]b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}static double[]normal(double[]a){double n=Math.sqrt(dot(a,a));if(n<1e-8)return new double[]{0,0,1};return new double[]{a[0]/n,a[1]/n,a[2]/n};}static double[]cross(double[]a,double[]b){return new double[]{a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
 static void pose(Lamp l,float partial){double[]eye;try{eye=Matrix6.xyz(R.call(l.owner,"getEyePosition",partial));}catch(IllegalStateException absent){eye=Matrix6.xyz(R.call(l.owner,"getEyePosition"));}try{l.forward=normal(Matrix6.xyz(R.call(l.owner,"getViewVector",partial)));}catch(IllegalStateException absent){l.forward=normal(Matrix6.xyz(R.call(l.owner,"getLookAngle")));}l.right=normal(cross(l.forward,Math.abs(l.forward[1])>.98?new double[]{0,0,1}:new double[]{0,1,0}));l.up=normal(cross(l.right,l.forward));l.origin=plus(plus(plus(eye,l.forward,.12),l.right,-.15),l.up,-.12);}
 static boolean source(Object p){return Power.on(R.call(p,"getMainHandItem"))||Power.on(R.call(p,"getOffhandItem"));}
 static void settings(Lamp l){Object a=R.call(l.owner,"getMainHandItem"),b=R.call(l.owner,"getOffhandItem"),s=Power.on(a)?a:b;int t=Power.tier(s);l.range=Power.RANGE[t];l.tan=Math.tan(Math.toRadians(t==3?16:t==2?25:20));}
 public static void safeTick(){if(Engine6.failed)return;try{tick();}catch(RuntimeException e){Engine6.failed=true;System.err.println("[Flashlight8] Light update disabled: "+e);e.printStackTrace();}}
 public static void tick(){Object m=mc(),level=R.get(m,"level"),p=R.get(m,"player");if(level!=world){world=level;cache.clear();blockEntities.clear();ticks=0;turn=0;}lastRays=0;if(level==null||p==null)return;List<Object>chosen=new ArrayList<>();if(source(p))chosen.add(p);try{for(Object other:(Iterable<?>)R.call(level,"players")){if(other==p||chosen.size()>=MAX||!source(other))continue;double dx=num(R.call(other,"getX"))-num(R.call(p,"getX")),dz=num(R.call(other,"getZ"))-num(R.call(p,"getZ"));if(dx*dx+dz*dz<48*48)chosen.add(other);}}catch(IllegalStateException absent){}cache.keySet().retainAll(chosen);for(Object owner:chosen){Lamp l=cache.get(owner);if(l==null){l=new Lamp(owner);settings(l);pose(l,1);l.shadowOrigin=l.origin.clone();l.shadowForward=l.forward.clone();l.shadowRight=l.right.clone();l.shadowUp=l.up.clone();double centre=trace(l,l.origin,l.forward)*dot(l.forward,l.forward);lastRays++;Arrays.fill(l.distance,(float)l.range);cache.put(owner,l);}settings(l);pose(l,1);}
  var lamps=new ArrayList<>(cache.values());while(!lamps.isEmpty()&&lastRays<BUDGET){Lamp l=lamps.get(Math.floorMod(turn++,lamps.size()));sample(l);lastRays++;}if(lamps.isEmpty())blockEntities.clear();else if(++ticks%10==1)blocks(lamps);}
 static void blocks(List<Lamp>lamps){blockEntities.clear();try{Object source=R.call(world,"getChunkSource"),status;try{status=R.get(R.type("net.minecraft.world.level.chunk.status.ChunkStatus"),"FULL");}catch(IllegalStateException legacy){status=R.get(R.type("net.minecraft.world.level.chunk.ChunkStatus"),"FULL");}Set<Object>seen=Collections.newSetFromMap(new IdentityHashMap<>());for(Lamp l:lamps){int cx=(int)Math.floor(l.origin[0]/16),cz=(int)Math.floor(l.origin[2]/16),radius=(int)Math.ceil(l.range/16);for(int ring=0;ring<=radius;ring++)for(int x=-ring;x<=ring;x++)for(int z=-ring;z<=ring;z++){if(ring>0&&Math.max(Math.abs(x),Math.abs(z))!=ring)continue;Object chunk=R.call(source,"getChunk",cx+x,cz+z,status,false);if(chunk==null)continue;Object raw=R.call(chunk,"getBlockEntities");if(raw instanceof Map<?,?>m)for(Object be:m.values())if(seen.add(be)){blockEntities.add(be);if(blockEntities.size()>=128)return;}}}}catch(IllegalStateException unavailable){}}
 static void sample(Lamp l){if(l.cursor==0){l.workingOrigin=l.origin.clone();l.workingForward=l.forward.clone();l.workingRight=l.right.clone();l.workingUp=l.up.clone();}int x=l.cursor%SIZE,y=l.cursor/SIZE;double u=((x+.5)/SIZE*2-1)*l.tan*1.4,v=((y+.5)/SIZE*2-1)*l.tan*1.4;double[]dir=normal(plus(plus(l.workingForward,l.workingRight,u),l.workingUp,v));l.working[l.cursor]=(float)(trace(l,l.workingOrigin,dir)*dot(dir,l.workingForward));if(++l.cursor==SIZE*SIZE){float[]swap=l.distance;l.distance=l.working;l.working=swap;l.shadowOrigin=l.workingOrigin;l.shadowForward=l.workingForward;l.shadowRight=l.workingRight;l.shadowUp=l.workingUp;l.cursor=0;}}
 static double trace(Lamp l,double[]from,double[]dir){double[]end=plus(from,dir,l.range);Object ctx=R.make("net.minecraft.world.level.ClipContext",vec(from),vec(end),R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),l.owner);Object hit=R.call(world,"clip",ctx);if(!"BLOCK".equals(R.call(hit,"getType").toString()))return l.range;double[]p=Matrix6.xyz(R.call(hit,"getLocation"));return Math.max(0,Math.min(l.range,Math.sqrt(Math.pow(p[0]-from[0],2)+Math.pow(p[1]-from[1],2)+Math.pow(p[2]-from[2],2))));}
 static Object vec(double[]v){return R.make("net.minecraft.world.phys.Vec3",v[0],v[1],v[2]);}
 static List<Lamp>render(float partial){var out=new ArrayList<Lamp>();for(Lamp l:cache.values())if(source(l.owner)){pose(l,partial);out.add(l);}return out;}
}
